import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';
import {parseCadProject,createCadProject,serializeCadProject} from '../../src/cad-project.js';import {applyCadJointRequest,rebindCadJointReferences,cadJointProblems,compileCadJointMotion} from '../../src/cad-joints-data.js';import {cadPoint,multiplyCadMatrices,inverseCadMatrix} from '../../src/cad-affine.js';import {encodeFnpackProject} from '../../src/cad-fnpack-data.js';import {createRequire} from 'node:module';
const {writeFnpack,openFnpack}=createRequire(import.meta.url)('../../backend/fnpack.cjs');const sha=x=>createHash('sha256').update(x).digest('hex');
export async function runCncFinal(service,file,step){
 const raw=fs.readFileSync(file),original=parseCadProject(raw.toString('utf8')),p=structuredClone(original),out=path.resolve(process.env.FORMNARO_CNC_FINAL_DIR||'work/cnc-final');fs.mkdirSync(out,{recursive:true});const repaired=[];
 for(const old of p.nodes.filter(n=>/Spindelmutter/.test(n.name)&&n.recipe?.type==='tube')){
  step('native-internal-thread-'+repaired.length);const diameter=old.name.startsWith('Z')?10:12,pitch=diameter===10?2:4,length=old.recipe.size[2],outerDiameter=old.recipe.size[0],fresh=service.nativeNode({type:'thread',size:[outerDiameter,outerDiameter,length],params:{kind:'nut',profile:'trapezoid',diameter,pitch,length,hand:'right',starts:1,phase:0,clearance:.18,outerShape:'round',outerDiameter,head:'none',leadIn:0}},{id:old.id}),oldTransform=[...old.transform],oldCenter=old.stats.bounds.min.map((v,k)=>(v+old.stats.bounds.max[k])/2),newCenter=fresh.stats.bounds.min.map((v,k)=>(v+fresh.stats.bounds.max[k])/2),before=cadPoint(oldTransform,oldCenter),after=cadPoint(oldTransform,newCenter),transform=[...oldTransform];for(let k=0;k<3;k++)transform[12+k]+=before[k]-after[k];
  const replacement={...old,recipe:fresh.recipe,brep:fresh.brep,stats:fresh.stats,transform,name:old.name.replace(' · Innengewinde vereinfacht',' · natives Innengewinde')};delete replacement.geometryIdentity;p.nodes[p.nodes.findIndex(n=>n.id===old.id)]=replacement;
  for(const j of p.joints.joints){if(j.childId===old.id)j.childFrame=multiplyCadMatrices(multiplyCadMatrices(inverseCadMatrix(transform),oldTransform),j.childFrame);if(j.parentId===old.id)j.parentFrame=multiplyCadMatrices(multiplyCadMatrices(inverseCadMatrix(transform),oldTransform),j.parentFrame);}
  assert.equal(fresh.stats.solids,1);repaired.push({id:old.id,diameter,pitch,length,solids:fresh.stats.solids,volume:fresh.stats.volume});
 }
 assert.equal(repaired.length,3);step('couplings');const extension=p.joints.joints.find(j=>j.id==='cnc-jack-length'),table=p.joints.joints.find(j=>j.id==='cnc-A'),parent=p.nodes.find(n=>n.id===extension.parentId),frame=multiplyCadMatrices(parent.transform,extension.parentFrame),axis=frame.slice(8,11),a=table.value*Math.PI/180,y=p.joints.joints.find(j=>j.id==='cnc-Y').value,attachment=[110,-30+y-40*Math.cos(a)-8*Math.sin(a),94-40*Math.sin(a)+8*Math.cos(a)];
 applyCadJointRequest(p,{action:'rebind',jointId:extension.id,origin:attachment.map((v,k)=>v-axis[k]*extension.value),axis});applyCadJointRequest(p,{action:'drive-create',drive:{id:'cnc-tilt-actuator',kind:'actuator',table:'cnc-A',swivel:'cnc-jack-angle',extension:extension.id,attachment}});
 const driveRows=[];
 for(const [prefix,linear,pitch]of [['X','cnc-X',4],['Y','cnc-Y',4],['Z','cnc-Z',2],['Kipp','cnc-jack-length',2]]){
  const nodes=p.nodes.filter(n=>n.name.startsWith(prefix+'-Spindelsegment'));assert.ok(nodes.length>1);const first=nodes[0],old=p.joints.joints.find(j=>j.childId===first.id),slide=p.joints.joints.find(j=>j.id===linear),carrier=p.nodes.find(n=>n.id===slide.parentId),f=multiplyCadMatrices(carrier.transform,slide.parentFrame),origin=cadPoint(first.transform,first.stats.bounds.min.map((v,k)=>(v+first.stats.bounds.max[k])/2)),axis=f.slice(8,11);
  const id=old.id;applyCadJointRequest(p,{action:'remove',jointId:id});applyCadJointRequest(p,{action:'create',joint:{id,name:prefix+'-Spindeldrehung',kind:'revolute',parentId:old.parentId,childId:first.id,origin,axis,limits:{min:-36000,max:36000}}});
  for(const node of nodes.slice(1)){const j=p.joints.joints.find(j=>j.childId===node.id),parentNode=p.nodes.find(n=>n.id===j.parentId),world=multiplyCadMatrices(parentNode.transform,j.parentFrame);p.joints=rebindCadJointReferences(p,[{jointId:j.id,parentId:first.id,origin:world.slice(12,15),axis:world.slice(8,11)}]);}
  applyCadJointRequest(p,{action:'drive-create',drive:{id:'cnc-screw-'+prefix,kind:'screw',rotary:id,linear,lead:pitch,direction:1}});driveRows.push({prefix,rotary:id,linear,lead:pitch,segments:nodes.length});
 }
 assert.deepEqual(cadJointProblems(p),[]);const motion=compileCadJointMotion(p),rows=[];let endpointError=0;
 for(const angle of [-15,0,15]){const pose=motion.preview([{jointId:'cnc-A',value:angle},{jointId:'cnc-X',value:0},{jointId:'cnc-Y',value:0},{jointId:'cnc-Z',value:25}]),transforms=new Map(pose.placements.map(p=>[p.rootId,p.transform])),j=p.joints.joints.find(j=>j.id==='cnc-jack-length'),end=multiplyCadMatrices(transforms.get(j.childId)??p.nodes.find(n=>n.id===j.childId).transform,j.childFrame),r=angle*Math.PI/180,tip=[110,-30-40*Math.cos(r)-8*Math.sin(r),94-40*Math.sin(r)+8*Math.cos(r)];endpointError=Math.max(endpointError,Math.hypot(...tip.map((v,k)=>v-end[12+k])));rows.push(pose.values.filter(v=>['cnc-A','cnc-jack-angle','cnc-jack-length'].includes(v.jointId)));}assert.ok(endpointError<1e-7);
 const lockedGeometry=p.nodes.filter(n=>!repaired.some(r=>r.id===n.id));for(const n of lockedGeometry)assert.equal(n.brep.data,original.nodes.find(x=>x.id===n.id).brep.data);
 step('save');const final=createCadProject(p),ocad=serializeCadProject(final),ocadFile=path.join(out,'CNC-mit-Kopplungen-und-Innengewinden.ocad');fs.writeFileSync(ocadFile,ocad);assert.deepEqual(parseCadProject(ocad).joints,final.joints);const encoded=encodeFnpackProject(final),packageFile=path.join(out,'CNC-mit-Kopplungen-und-Innengewinden.fnpack');await writeFnpack(packageFile,encoded);const opened=await openFnpack(packageFile);try{assert.deepEqual(opened.index.project.joints,final.joints);}finally{await opened.close();}assert.equal(sha(fs.readFileSync(file)),sha(raw));
 return {status:'completed',roots:final.nodes.length,joints:final.joints.joints.length,drives:final.joints.drives.length,realInternalThreads:repaired,driveRows,rows,endpointError,unchangedOtherBReps:lockedGeometry.length,inputUnchanged:true,ocadFile,packageFile,ocadBytes:Buffer.byteLength(ocad),sourceSha256:sha(raw),memory:service.memoryState(),scope:'Copy with explicit datum repair, real internal threads and native coupled kinematics; no continuous collision, contact or manufacturing clearance guarantee.'};
}
